package fr.bbodin.courbedepoids;import org.junit.Test;import static org.junit.Assert.*;public class WeightDatabaseValidationTest{@Test public void acceptsValidWeightPayload(){assertTrue(WeightDatabase.isValidGenericEvent("weight","2026-10-12",1,"{\"weight_kg\":82.4}"));}@Test public void rejectsInvalidWeightPayload(){assertFalse(WeightDatabase.isValidGenericEvent("weight","2026-10-12",1,"{\"weight_kg\":0}"));}@Test public void acceptsWaterAndSportPayloads(){assertTrue(WeightDatabase.isValidGenericEvent("water","2026-10-12",1,"{\"amount_ml\":500}"));assertTrue(WeightDatabase.isValidGenericEvent("sport","2026-10-12",1,"{\"activity\":\"Course\",\"duration_minutes\":30,\"distance_km\":5.0}"));}@Test public void rejectsMalformedGenericEvents(){assertFalse(WeightDatabase.isValidGenericEvent("unknown type","2026-10-12",1,"{}"));assertFalse(WeightDatabase.isValidGenericEvent("weight","bad-date",1,"{\"weight_kg\":80}"));assertFalse(WeightDatabase.isValidGenericEvent("weight","2026-10-12",-1,"{\"weight_kg\":80}"));}}